qualified_questions.sparql_query:
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX VideoGameOntology: <http://example.com/VideoGameOntology#>

SELECT ?property ?domain ?range
WHERE {
  ?property rdf:type owl:ObjectProperty ;
            rdfs:domain ?domain ;
            rdfs:range ?range .
}

PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX VideoGameOntology: <http://example.org/VideoGameOntology/>

SELECT ?class ?superClass
WHERE {
  ?class rdf:type owl:Class ;
         rdfs:subClassOf ?superClass .
  FILTER(?superClass != owl:Thing)
}

PREFIX VideoGameOntology: <http://example.org/VideoGameOntology#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX foaf: <http://xmlns.com/foaf/0.1/>

SELECT (COUNT(DISTINCT ?player) AS ?numberOfPlayers)
WHERE {
  ?player VideoGameOntology:playsGame ?game .
  ?friend VideoGameOntology:isFriendWithPlayer ?player ;
          VideoGameOntology:playsGame ?game .
  ?session1 VideoGameOntology:involvesCharacter ?character ;
            VideoGameOntology:playsGame ?game ;
            VideoGameOntology:startTime ?time1 .
  ?session2 VideoGameOntology:involvesCharacter ?character ;
            VideoGameOntology:playsGame ?game ;
            VideoGameOntology:startTime ?time2 .
  FILTER(?player != ?friend)
  FILTER(?time1 = ?time2)
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX foaf: <http://xmlns.com/foaf/0.1/>
PREFIX VideoGameOntology: <http://example.org/VideoGameOntology#>

SELECT ?property ?domain ?range
WHERE {
  ?property rdf:type owl:ObjectProperty ;
            rdfs:subPropertyOf foaf:knows ;
            rdfs:domain ?domain ;
            rdfs:range ?range .
}
